import { readFileSync } from "node:fs";
import { defineConfig, type Plugin } from "vite";
import react from "@vitejs/plugin-react";

// VN-GEN-007: third-party notices for every bundled package ship with the app (generated by scripts/check-deps.mjs).
function thirdPartyNotices(): Plugin {
  return {
    name: "vastness-third-party-notices",
    apply: "build",
    generateBundle() {
      const source = readFileSync(new URL("./THIRD_PARTY_NOTICES.txt", import.meta.url), "utf8");
      this.emitFile({ type: "asset", fileName: "THIRD_PARTY_NOTICES.txt", source });
    },
  };
}

// VN-GEN-001: a static build. `base` becomes /vastness/ for GitHub Pages in T-007.
export default defineConfig({
  base: "./",
  plugins: [react(), thirdPartyNotices()],
  worker: { format: "es" },
});
